mapper.select:
SELECT f_cdnm('ProvideRcvType' , biz01_provide_rcv_type , biz01_company_id, biz01_provide_date) AS provide_rcv_type_name , biz01_reg_emp_nm AS reg_emp_name , biz01_provide_date AS provide_date , f_cdnm('ProvidePurCode' , biz01_provide_pur_cd , biz01_company_id, biz01_provide_date) AS provide_pur_name , f_cdnm('ProvideContentCode' , biz01_provide_content_cd , biz01_company_id, biz01_provide_date) AS provide_content_name , biz01_target_emp_nm AS target_emp_name , biz01_average_price AS average_price , biz01_note AS note FROM ( SELECT biz01_promo.* , CASE WHEN (SELECT COUNT(*) FROM biz02_person WHERE biz02_promo_id = biz01_promo_id AND biz02_emp_id = (CASE WHEN biz01_settle_type = '1' THEN f_get_crdManagerId(biz01_card_id, biz01_provide_date) ELSE biz01_reg_emp_id END)) = 0 AND COALESCE(biz02_emp_count,0) != 0 THEN biz02_emp_nm ELSE f_emp_kor_nm(CASE WHEN biz01_settle_type = '1' THEN f_get_crdManagerId(biz01_card_id, biz01_provide_date) ELSE biz01_reg_emp_id END) END ||CASE WHEN biz02_emp_count > 1 THEN ' 외 '||biz02_emp_count-1 ELSE '' END AS biz01_reg_emp_nm , biz02_target_nm||CASE WHEN biz02_target_count > 1 THEN ' 외 '||biz02_target_count-1 ELSE '' END AS biz01_target_emp_nm , TRUNC(biz01_provide_amt / (CASE WHEN biz01_provide_rcv_type = '2' THEN f_nvl(biz02_emp_count,1) ELSE f_nvl(biz02_count ,1) END)) AS biz01_average_price FROM biz01_promo LEFT OUTER JOIN LATERAL ( SELECT COUNT(*) biz02_count , f_emp_kor_nm(MAX(biz02_emp_id)) biz02_emp_nm , COALESCE(MAX(biz02_target_company_nm||' '||biz02_target_emp_nm),'*미등록*') biz02_target_nm , SUM(CASE WHEN COALESCE(biz02_emp_yn,'false') = 'true' THEN 1 ELSE 0 END) biz02_emp_count , SUM(CASE WHEN COALESCE(biz02_emp_yn,'false') = 'false' THEN 1 ELSE 0 END) biz02_target_count FROM biz02_person WHERE biz02_promo_id = biz01_promo_id ) biz02 ON TRUE WHERE biz01_company_id = #{companyId} AND biz01_provide_rcv_type like #{provideRcvType} AND to_char(biz01_provide_date,'yyyy') = #{yearText} AND SUBSTR(biz01_provide_pur_cd,1,1) in ('1','2') /* 10:판매(일반)/11:판매(경조)/20:운용(일반)/21:운용(경조)/50:관리(일반) */ ) a INNER JOIN biz90_limit ON ( biz90_company_id = biz01_company_id AND biz90_provide_rcv_type = biz01_provide_rcv_type AND biz90_start_date = ( SELECT MAX(biz90_start_date) FROM biz90_limit WHERE biz90_company_id = biz01_company_id AND biz90_provide_rcv_type = biz01_provide_rcv_type AND biz90_start_date <= biz01_provide_date ) ) WHERE 1=1 AND ( ( /*** 1:이익제공 한도체크 ***/ biz01_provide_rcv_type = '1' AND
/* 편익 기준액 적용 */ biz01_average_price > CASE WHEN SUBSTR(biz01_provide_pur_cd,2,1) = '0' THEN biz90_sale_rule_limit1 /* 일반 */ ELSE biz90_sale_rule_limit2 END /* 경조 */
biz01_average_price > COALESCE(#{limit1,jdbcType=NUMERIC}, 0)
biz01_average_price > biz90_company_limit1
) OR ( /*** 2:이익수령 한도체크 ***/ biz01_provide_rcv_type = '2' AND biz01_average_price > biz90_company_limit1 ) ) ORDER BY biz01_provide_date

WITH BIZ_BASE AS ( ), BIZ AS ( /*--- 이익제공 ---*/ SELECT biz01_provide_rcv_type , COALESCE(biz02_target_company_nm,'*미등록*') biz01_target_company_nm , COALESCE(biz02_target_emp_nm,'*미등록*') biz01_target_emp_nm , biz01_average_price , biz90_company_limit2 FROM BIZ_BASE LEFT OUTER JOIN biz02_person a ON a.biz02_promo_id = biz01_promo_id WHERE biz01_provide_rcv_type = '1' AND COALESCE(biz02_emp_yn,'false') != 'true'
/*--- 이익제공(거래상대방 미등록) ---*/ UNION ALL SELECT biz01_provide_rcv_type , '*미등록*' biz01_target_company_nm , '*미등록*' biz01_target_emp_nm , biz01_average_price , biz90_company_limit2 FROM BIZ_BASE WHERE biz01_provide_rcv_type = '1'
AND NOT EXISTS (SELECT 1 FROM biz02_person WHERE biz02_promo_id = biz01_promo_id AND biz02_target_emp_nm IS NOT NULL) /*--- 이익수령 ---*/ UNION ALL SELECT biz01_provide_rcv_type , f_get_company_nm(biz01_company_id) biz01_target_company_nm , f_emp_kor_nm(biz02_emp_id) biz01_target_emp_nm , biz01_average_price , biz90_company_limit2 FROM BIZ_BASE LEFT OUTER JOIN biz02_person a ON a.biz02_promo_id = biz01_promo_id WHERE biz01_provide_rcv_type = '2' AND COALESCE(biz02_emp_yn,'false') = 'true' /*--- 이익수령(직원정보 미등록) ---*/ UNION ALL SELECT biz01_provide_rcv_type , f_get_company_nm(biz01_company_id) biz01_target_company_nm , '*미등록*' biz01_target_emp_nm , biz01_average_price , biz90_company_limit2 FROM BIZ_BASE WHERE biz01_provide_rcv_type = '2' AND NOT EXISTS (SELECT 1 FROM biz02_person WHERE biz02_promo_id = biz01_promo_id AND biz02_emp_id IS NOT NULL) ) SELECT f_cdnm('ProvideRcvType', biz01_provide_rcv_type, #{companyId}, f_today()) AS provide_rcv_type_name , biz01_target_company_nm AS target_company_name , biz01_target_emp_nm AS target_emp_name , biz01_average_price AS average_price FROM ( SELECT biz01_provide_rcv_type , biz01_target_company_nm , biz01_target_emp_nm , SUM(biz01_average_price) biz01_average_price , biz90_company_limit2 FROM BIZ GROUP BY biz01_provide_rcv_type , biz01_target_company_nm , biz01_target_emp_nm , biz90_company_limit2 ) a WHERE ( ( biz01_provide_rcv_type = '1' AND biz01_average_price > COALESCE(#{limit2,jdbcType=NUMERIC}, 0)biz90_company_limit2 ) OR ( biz01_provide_rcv_type = '2' AND biz01_average_price > biz90_company_limit2 ) ) ORDER BY biz01_provide_rcv_type , biz01_target_company_nm collate "ko_KR.utf8" asc , biz01_target_emp_nm collate "ko_KR.utf8"

WITH BIZ_BASE AS ( ), BIZ AS ( /*--- 이익제공 ---*/ SELECT biz01_provide_rcv_type , COALESCE(biz02_target_company_nm,'*미등록*') biz01_target_company_nm , biz01_average_price , biz90_company_limit3 FROM BIZ_BASE LEFT OUTER JOIN biz02_person a ON a.biz02_promo_id = biz01_promo_id WHERE biz01_provide_rcv_type = '1' AND COALESCE(biz02_emp_yn,'false') != 'true'
/*--- 이익제공(거래상대방 미등록) ---*/ UNION ALL SELECT biz01_provide_rcv_type , '*미등록*' biz01_target_company_nm , biz01_average_price , biz90_company_limit3 FROM BIZ_BASE WHERE biz01_provide_rcv_type = '1'
AND NOT EXISTS (SELECT 1 FROM biz02_person WHERE biz02_promo_id = biz01_promo_id AND biz02_target_company_nm IS NOT NULL) /*--- 이익수령 ---*/ UNION ALL SELECT biz01_provide_rcv_type , f_get_company_nm(biz01_company_id) biz01_target_company_nm , biz01_average_price , biz90_company_limit3 FROM BIZ_BASE LEFT OUTER JOIN biz02_person a ON a.biz02_promo_id = biz01_promo_id WHERE biz01_provide_rcv_type = '2' AND COALESCE(biz02_emp_yn,'false') = 'true' /*--- 이익수령(직원정보 미등록) ---*/ UNION ALL SELECT biz01_provide_rcv_type , f_get_company_nm(biz01_company_id) biz01_target_company_nm , biz01_average_price , biz90_company_limit3 FROM BIZ_BASE WHERE biz01_provide_rcv_type = '2' AND NOT EXISTS (SELECT 1 FROM biz02_person WHERE biz02_promo_id = biz01_promo_id AND biz02_emp_id IS NOT NULL) ) SELECT f_cdnm('ProvideRcvType', biz01_provide_rcv_type, #{companyId}, f_today()) AS provide_rcv_type_name , biz01_target_company_nm AS target_company_name , biz01_average_price AS average_price FROM ( SELECT biz01_provide_rcv_type , biz01_target_company_nm , SUM(biz01_average_price) biz01_average_price , biz90_company_limit3 FROM BIZ GROUP BY biz01_provide_rcv_type , biz01_target_company_nm , biz90_company_limit3 ) a WHERE ( ( biz01_provide_rcv_type = '1' AND biz01_average_price > COALESCE(#{limit3,jdbcType=NUMERIC}, 0)biz90_company_limit3 ) OR ( biz01_provide_rcv_type = '2' AND biz01_average_price > biz90_company_limit3 ) ) ORDER BY biz01_provide_rcv_type, biz01_target_company_nm collate "ko_KR.utf8" asc
